mapper.select:
SELECT COUNT(*)
  FROM fnd26_terms_detail
       INNER JOIN fnd25_terms ON fnd25_terms_id = fnd26_terms_id
 WHERE fnd26_terms_id    = #{termsId}
   AND fnd26_revision_no = #{revisionNo}

   AND fnd26_revision_no != #{originRevisionNo}

SELECT COUNT(*)
  FROM fnd25_terms
 WHERE fnd25_fund_id = #{fundId}

   AND fnd25_fund_id != #{originFundId}
